-- Closed release infrastructure only. Actual policy/source contracts require later reviewed seeds.
create function private_mfa_nl_history.release_require(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'MFA_NL_RELEASE: %',message;end if;end$$;
create function private_mfa_nl_history.canonical_json(p_value jsonb)returns text language plpgsql immutable strict as $$
declare result text;begin
 case jsonb_typeof(p_value)
 when 'object'then select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||private_mfa_nl_history.canonical_json(value),','order by key collate "C"),'')||'}'into result from jsonb_each(p_value);
 when 'array'then select '['||coalesce(string_agg(private_mfa_nl_history.canonical_json(value),','order by ord),'')||']'into result from jsonb_array_elements(p_value)with ordinality x(value,ord);
 else result:=p_value::text;end case;return result;
end$$;
create table private_mfa_nl_history.source_contract(
 competition_id bigint primary key check(competition_id in(973,974)),
 contract_sha256 text not null unique check(contract_sha256~'^[a-f0-9]{64}$'),document jsonb not null);
create table private_mfa_nl_history.import_receipt(
 competition_id bigint not null references private_mfa_nl_history.source_contract,main_sha text not null,
 contract_sha text not null,bootstrap_before_sha text not null,football_sha text not null,football_image_text text not null,
 recorded_at timestamptz not null default clock_timestamp(),primary key(competition_id,main_sha));
create table private_mfa_nl_history.price_receipt(
 competition_id bigint not null,main_sha text not null,contract_sha text not null,football_sha text not null,
 state_sha text not null,recorded_at timestamptz not null default clock_timestamp(),primary key(competition_id,main_sha),
 foreign key(competition_id,main_sha)references private_mfa_nl_history.import_receipt);
create table private_mfa_nl_history.release_receipt(
 competition_id bigint primary key references private_mfa_nl_history.source_contract,main_sha text not null,
 contract_sha text not null,preview_sha text not null,result jsonb not null,activated_at timestamptz not null default clock_timestamp());
revoke all on all tables in schema private_mfa_nl_history from public,anon,authenticated,service_role;
create function private_mfa_nl_history.contract_guard()returns trigger language plpgsql as $$begin
 if tg_op<>'INSERT'then raise exception 'MFA_NL_RELEASE: reviewed source contract immutable';end if;
 perform private_mfa_nl_history.release_require(new.document->>'competitionId'=new.competition_id::text and new.contract_sha256=encode(sha256(convert_to(private_mfa_nl_history.canonical_json(new.document),'UTF8')),'hex'),'contract SHA must cover the complete canonical document');return new;
end$$;
create trigger mfa_nl_source_contract_immutable before insert or update or delete on private_mfa_nl_history.source_contract for each row execute function private_mfa_nl_history.contract_guard();

create function private_mfa_nl_history.contract(p_id bigint,p_sha text)returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare t record;doc jsonb;artifact jsonb;item jsonb;begin
 select *into t from private_mfa_nl_history.target(p_id);
 perform private_mfa_nl_history.release_require(t.id is not null,'fixed native target required');
 select document into doc from private_mfa_nl_history.source_contract where competition_id=p_id and contract_sha256=p_sha;
 perform private_mfa_nl_history.release_require(doc is not null and p_sha~'^[a-f0-9]{64}$'and p_sha=encode(sha256(convert_to(private_mfa_nl_history.canonical_json(doc),'UTF8')),'hex'),'stored immutable source contract/hash required');
 perform private_mfa_nl_history.release_require(doc-array['schemaVersion','competitionId','policyId','policySha256','archiveSeason','currentSeason','expectedArchiveRounds','expectedCurrentFixtureCount','expectedCurrentClubCount','sourceArtifact','opening','reports','currentFixtures']='{}'::jsonb and doc->>'schemaVersion'='1'and doc->>'competitionId'=p_id::text and doc->>'policyId'=t.policy_id and doc->>'archiveSeason'='2025/26'and doc->>'currentSeason'='2026/27','source contract identity/schema differs');
 perform private_mfa_nl_history.policy(p_id,doc->>'policySha256');
 perform private_mfa_nl_history.release_require(exists(select 1 from competitions c join countries d on d.id=c.country_id join federations f on f.id=c.federation_id and f.country_id=c.country_id where c.id=p_id and c.slug=t.slug and c.source='mfa'and c.source_league_code=t.code and not c.sezona_koledarska and c.date_only_deadline_policy is null and(c.source_policy is null or c.source_policy=t.source_policy)and d.code='MT'and f.code='mfa'),'exact native source-contract tuple required');
 for item in select value from jsonb_each(doc)where key in('expectedArchiveRounds','expectedCurrentFixtureCount','expectedCurrentClubCount')loop
  perform private_mfa_nl_history.release_require(jsonb_typeof(item)='number'and item::text~'^[1-9][0-9]*$'and pg_input_is_valid(item::text,'integer'),'reviewed positive integer source counts required');
 end loop;
 perform private_mfa_nl_history.release_require(doc?'expectedArchiveRounds'and doc?'expectedCurrentFixtureCount'and doc?'expectedCurrentClubCount','complete reviewed count fields required');
 artifact:=doc->'sourceArtifact';
 perform private_mfa_nl_history.release_require(jsonb_typeof(artifact)='object'and artifact-array['runId','artifactId','digest','commit','workflow','branch','name']='{}'::jsonb and artifact->>'runId'~'^[1-9][0-9]*$'and artifact->>'artifactId'~'^[1-9][0-9]*$'and artifact->>'digest'~'^sha256:[a-f0-9]{64}$'and artifact->>'commit'~'^[a-f0-9]{40}$'and artifact->>'workflow'~'^\.github/workflows/[A-Za-z0-9_-]+\.ya?ml$'and length(artifact->>'branch')>0 and length(artifact->>'name')>0,'exact reviewed source artifact provenance required');
 item:=doc->'opening';
 perform private_mfa_nl_history.release_require(jsonb_typeof(item)='object'and item-array['round','playedOn','deadlineAt']='{}'::jsonb and jsonb_typeof(item->'round')='number'and item->>'round'~'^[1-9][0-9]*$'and pg_input_is_valid(item->>'round','integer')and item->>'playedOn'~'^202[67]-[0-9]{2}-[0-9]{2}$'and pg_input_is_valid(item->>'playedOn','date')and item->>'deadlineAt'~'T.*Z$'and pg_input_is_valid(item->>'deadlineAt','timestamp with time zone'),'reviewed source opening round/date/UTC deadline required');
 perform private_mfa_nl_history.release_require(jsonb_typeof(doc->'reports')='array'and jsonb_typeof(doc->'currentFixtures')='array','complete report and current fixture arrays required');
 perform private_mfa_nl_history.release_require(jsonb_array_length(doc->'reports')>0 and jsonb_array_length(doc->'currentFixtures')=(doc->>'expectedCurrentFixtureCount')::int,'source contract count differs');
 for item in select value from jsonb_array_elements(doc->'reports')loop
  perform private_mfa_nl_history.release_require(item-array['reportId','season','round','playedOn','homeName','awayName','homeGoals','awayGoals','statisticsStatus']='{}'::jsonb and item->>'reportId'~'^mt[1-9][0-9]*$'and item->>'season'in('2025/26','2026/27')and jsonb_typeof(item->'round')='number'and item->>'round'~'^[1-9][0-9]*$'and pg_input_is_valid(item->>'round','integer')and item->>'playedOn'~'^202[567]-[0-9]{2}-[0-9]{2}$'and pg_input_is_valid(item->>'playedOn','date')and length(item->>'homeName')>0 and length(item->>'awayName')>0 and item->>'homeName'<>item->>'awayName'and jsonb_typeof(item->'homeGoals')='number'and item->>'homeGoals'~'^[0-9]+$'and pg_input_is_valid(item->>'homeGoals','integer')and jsonb_typeof(item->'awayGoals')='number'and item->>'awayGoals'~'^[0-9]+$'and pg_input_is_valid(item->>'awayGoals','integer')and(item->>'statisticsStatus'='available'or(item->>'statisticsStatus'='unavailable_historical'and item->>'season'='2025/26')),'invalid exact source report header');
 end loop;
 for item in select value from jsonb_array_elements(doc->'currentFixtures')loop
  perform private_mfa_nl_history.release_require(item-array['sourceMatchId','round','playedOn','homeName','awayName','played']='{}'::jsonb and item->>'sourceMatchId'~'^[1-9][0-9]*$'and jsonb_typeof(item->'round')='number'and item->>'round'~'^[1-9][0-9]*$'and pg_input_is_valid(item->>'round','integer')and item->>'playedOn'~'^202[67]-[0-9]{2}-[0-9]{2}$'and pg_input_is_valid(item->>'playedOn','date')and length(item->>'homeName')>0 and length(item->>'awayName')>0 and item->>'homeName'<>item->>'awayName'and jsonb_typeof(item->'played')='boolean','invalid exact current source fixture');
 end loop;
 perform private_mfa_nl_history.release_require((select count(distinct x->>'reportId')from jsonb_array_elements(doc->'reports')x)=jsonb_array_length(doc->'reports')and(select count(distinct(x->>'season',x->>'round',x->>'homeName',x->>'awayName'))from jsonb_array_elements(doc->'reports')x)=jsonb_array_length(doc->'reports')and(select count(distinct x->>'sourceMatchId')from jsonb_array_elements(doc->'currentFixtures')x)=jsonb_array_length(doc->'currentFixtures')and(select count(distinct(x->>'round',x->>'homeName',x->>'awayName'))from jsonb_array_elements(doc->'currentFixtures')x)=jsonb_array_length(doc->'currentFixtures'),'duplicate source or logical fixture identity');
 return doc;
end$$;

create function private_mfa_nl_history.release_lock(p_id bigint,p_main_sha text)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform private_mfa_nl_history.lock_scope(p_id,p_main_sha);
 lock table private_mfa_nl_history.source_contract,private_mfa_nl_history.import_receipt,private_mfa_nl_history.price_receipt,private_mfa_nl_history.release_receipt in share row exclusive mode;
 perform private_mfa_nl_history.release_require(exists(select 1 from competitions where id=p_id and not active),'inactive native candidate required');
 -- Activity may arrive between bootstrap and release; never rely on the old check.
 perform private_mfa_nl_history.release_require(not exists(select 1 from fantasy_teams where competition_id=p_id)and not exists(select 1 from fantasy_roster fr join players p on p.id=fr.player_id where p.competition_id=p_id)and not exists(select 1 from fantasy_lineups l left join players p on p.id=l.player_id left join rounds r on r.id=l.round_id where p.competition_id=p_id or r.competition_id=p_id)and not exists(select 1 from fantasy_transfers f join rounds r on r.id=f.round_id where r.competition_id=p_id)and not exists(select 1 from fantasy_chips f join rounds r on r.id=f.round_id where r.competition_id=p_id),'fantasy dependency/activity exists');
 perform private_mfa_nl_history.release_require(not exists(select 1 from position_votes v join players p on p.id=v.player_id where p.competition_id=p_id)and not exists(select 1 from position_votes_deleted v join players p on p.id=v.player_id where p.competition_id=p_id)and not exists(select 1 from assist_votes v left join goals g on g.id=v.goal_id left join matches m on m.id=g.match_id left join rounds r on r.id=m.round_id left join players p on p.id=v.player_id where r.competition_id=p_id or p.competition_id=p_id)and not exists(select 1 from assist_votes_deleted v left join goals g on g.id=v.goal_id left join matches m on m.id=g.match_id left join rounds r on r.id=m.round_id left join players p on p.id=v.player_id where r.competition_id=p_id or p.competition_id=p_id),'current/deleted vote activity exists');
 perform private_mfa_nl_history.release_require(not exists(select 1 from uradne_odsotnosti u join players p on p.id=u.player_id where p.competition_id=p_id)and not exists(select 1 from profil_igralca_plus v left join players p on p.id=v.player_id left join matches m on m.id=v.tekma_id left join rounds r on r.id=m.round_id where p.competition_id=p_id or r.competition_id=p_id)and not exists(select 1 from anonimizirani_igralci a join players p on p.id=a.player_id where p.competition_id=p_id),'player-owned/anonymous dependencies exist');
end$$;

create function private_mfa_nl_history.coverage(p_id bigint,doc jsonb,p_clock timestamptz)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare bootstrap private_mfa_nl_history.bootstrap_receipt%rowtype;binding jsonb;original jsonb;current_opening jsonb;headers jsonb;fixtures jsonb;country bigint;begin
 select *into bootstrap from private_mfa_nl_history.bootstrap_receipt where competition_id=p_id;
 binding:=public.get_installed_historical_statistics_markers(p_id);
 perform private_mfa_nl_history.release_require(bootstrap.competition_id=p_id and bootstrap.policy_sha=doc->>'policySha256'and binding->>'policyId'=doc->>'policyId'and binding->>'policySha256'=doc->>'policySha256','installed bootstrap/policy binding required');
 original:=bootstrap.before_image_text::jsonb->'opening';current_opening:=private_mfa_nl_history.opening(p_id,p_clock);
 perform private_mfa_nl_history.release_require(original=current_opening and original->'round'->>'number'=doc->'opening'->>'round'and(original->'round'->>'played_on')::date=(doc->'opening'->>'playedOn')::date and(original->'round'->>'deadline_at')::timestamptz=(doc->'opening'->>'deadlineAt')::timestamptz and exists(select 1 from competitions where id=p_id and source_policy=(select source_policy from private_mfa_nl_history.target(p_id))and prvi_fantasy_krog=(doc->'opening'->>'round')::int),'reviewed source/bootstrap/native opening differs');
 select country_id into country from competitions where id=p_id;
 select coalesce(jsonb_agg(jsonb_build_object('reportId',x->>'reportId','matchId',m.id,'roundId',r.id,'homeTeamId',h.id,'awayTeamId',a.id)order by x->>'reportId'),'[]')into headers
 from jsonb_array_elements(doc->'reports')x join matches m on m.zapisnik_id=x->>'reportId'join rounds r on r.id=m.round_id and r.competition_id=p_id and r.season=x->>'season'and r.number=(x->>'round')::int
 join teams h on h.id=m.home_team_id and h.country_id=country and h.name=x->>'homeName'join teams a on a.id=m.away_team_id and a.country_id=country and a.name=x->>'awayName'
 where m.played_on=(x->>'playedOn')::date and m.home_goals=(x->>'homeGoals')::int and m.away_goals=(x->>'awayGoals')::int and m.statistics_status=x->>'statisticsStatus'and m.source_url='https://matchcentre.mfa.com.mt/match/'||substring(x->>'reportId'from 3)and not m.kontumacija and not m.vir_brez_izida and((m.statistics_status='available'and m.imported_at is not null)or(m.statistics_status='unavailable_historical'and m.imported_at is null));
 perform private_mfa_nl_history.release_require(jsonb_array_length(headers)=jsonb_array_length(doc->'reports')and not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=p_id and(m.zapisnik_id is not null or m.imported_at is not null or m.statistics_status<>'available')and not exists(select 1 from jsonb_array_elements(headers)x where(x->>'matchId')::bigint=m.id)),'exact source/native report header set differs');
 perform private_mfa_nl_history.release_require((select count(*)from jsonb_array_elements(doc->'reports')x where x->>'statisticsStatus'='unavailable_historical')=jsonb_array_length(binding->'markers')and not exists(select 1 from jsonb_array_elements(binding->'markers')mk where not exists(select 1 from jsonb_array_elements(doc->'reports')x where x->>'reportId'=mk->>'reportId'and x->>'statisticsStatus'='unavailable_historical')),'source contract marker set differs');
 select coalesce(jsonb_agg(jsonb_build_object('sourceMatchId',x->>'sourceMatchId','matchId',m.id,'roundId',r.id,'homeTeamId',h.id,'awayTeamId',a.id,'indirect',not(x->>'played')::boolean)order by x->>'sourceMatchId'),'[]')into fixtures
 from jsonb_array_elements(doc->'currentFixtures')x join rounds r on r.competition_id=p_id and r.season='2026/27'and r.number=(x->>'round')::int join matches m on m.round_id=r.id and m.played_on=(x->>'playedOn')::date
 join teams h on h.id=m.home_team_id and h.country_id=country and h.name=x->>'homeName'join teams a on a.id=m.away_team_id and a.country_id=country and a.name=x->>'awayName'
 where((x->>'played')::boolean and m.zapisnik_id='mt'||(x->>'sourceMatchId')and exists(select 1 from jsonb_array_elements(doc->'reports')rp where rp->>'reportId'=m.zapisnik_id and rp->>'season'='2026/27'))or(not(x->>'played')::boolean and m.zapisnik_id is null and m.source_url is null and m.imported_at is null and m.home_goals=0 and m.away_goals=0 and m.statistics_status='available'and not m.kontumacija and not m.vir_brez_izida and not exists(select 1 from appearances where match_id=m.id)and not exists(select 1 from goals where match_id=m.id));
 perform private_mfa_nl_history.release_require(jsonb_array_length(fixtures)=(doc->>'expectedCurrentFixtureCount')::int and(select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=p_id and r.season='2026/27')=jsonb_array_length(fixtures),'exact current source/native fixture set differs');
 perform private_mfa_nl_history.release_require((select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=p_id and r.season='2025/26')=(select count(*)from jsonb_array_elements(doc->'reports')x where x->>'season'='2025/26')and(select count(*)from rounds where competition_id=p_id and season='2025/26')=(doc->>'expectedArchiveRounds')::int and(select min(number)=1 and max(number)=(doc->>'expectedArchiveRounds')::int from rounds where competition_id=p_id and season='2025/26')and not exists(select 1 from rounds r where r.competition_id=p_id and(r.season not in('2025/26','2026/27')or(r.season='2026/27'and not exists(select 1 from jsonb_array_elements(doc->'currentFixtures')x where(x->>'round')::int=r.number)))),'exact archive/current season and round coverage differs');
 perform private_mfa_nl_history.release_require((select count(distinct tid)from jsonb_array_elements(fixtures)x cross join lateral(values((x->>'homeTeamId')::bigint),((x->>'awayTeamId')::bigint))v(tid))=(doc->>'expectedCurrentClubCount')::int,'exact current source club set differs');
 return jsonb_build_object('headerBindings',headers,'fixtureBindings',fixtures,'opening',original,'markers',binding,'bootstrapBeforeSha256',bootstrap.before_sha);
end$$;

create function private_mfa_nl_history.football_image(p_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare image jsonb;part jsonb;q record;begin
 image:=jsonb_build_object('competition',(select to_jsonb(c)-'active'from competitions c where id=p_id));
 for q in select *from(values
 ('players','select id,competition_id,team_id,reg_st,first_name,last_name,full_name,shirt_number,nzs_birth_year from players where competition_id=$1'),
 ('teams','select t.*from teams t where t.id in(select team_id from players where competition_id=$1 union select m.home_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=$1 union select m.away_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=$1)'),
 ('rounds','select *from rounds where competition_id=$1'),('matches','select m.*from matches m join rounds r on r.id=m.round_id where r.competition_id=$1'),
 ('appearances','select a.*from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=$1'),
 ('goals','select g.*from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=$1'))v(key,query)loop
 execute 'select coalesce(jsonb_agg(to_jsonb(t)order by id),''[]''::jsonb)from('||q.query||')t'into part using p_id;image:=image||jsonb_build_object(q.key,part);end loop;return image;
end$$;
create function private_mfa_nl_history.football_integrity(p_id bigint)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform private_mfa_nl_history.release_require(not exists(select 1 from players where competition_id=p_id and(reg_st is null or reg_st<=0))and not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=p_id and m.imported_at is not null and(m.home_goals is distinct from(select count(*)::int from goals g where g.match_id=m.id and((g.team_id=m.home_team_id and not g.is_own_goal)or(g.team_id=m.away_team_id and g.is_own_goal)))or m.away_goals is distinct from(select count(*)::int from goals g where g.match_id=m.id and((g.team_id=m.away_team_id and not g.is_own_goal)or(g.team_id=m.home_team_id and g.is_own_goal)))or exists(select 1 from(values(m.home_team_id),(m.away_team_id))v(tid)where(select count(*)from appearances a where a.match_id=m.id and a.team_id=v.tid and a.started)<>11))),'complete score/XI/source-player identity required');
 perform private_mfa_nl_history.release_require(not exists(select 1 from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=p_id and(g.minute is null or g.minute<0 or g.minute>90 or not exists(select 1 from appearances a where a.match_id=g.match_id and a.player_id=g.scorer_id and a.team_id=g.team_id)))and not exists(select 1 from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id join players p on p.id=a.player_id where r.competition_id=p_id and(p.competition_id<>p_id or a.team_id not in(m.home_team_id,m.away_team_id)or a.minutes_played is null or a.minute_on is null or a.minute_off is null or a.minute_on<0 or a.minute_off>90 or a.minute_on>a.minute_off or a.minutes_played<>a.minute_off-a.minute_on)),'native goal/appearance team/player/minute identity differs');
end$$;
create function private_mfa_nl_history.source_state_core(p_id bigint,p_main_sha text,p_contract_sha text,p_clock timestamptz)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare doc jsonb;binding jsonb;image text;begin
 perform private_mfa_nl_history.release_lock(p_id,p_main_sha);doc:=private_mfa_nl_history.contract(p_id,p_contract_sha);binding:=private_mfa_nl_history.coverage(p_id,doc,p_clock);perform private_mfa_nl_history.football_integrity(p_id);image:=private_mfa_nl_history.football_image(p_id)::text;
 return binding||jsonb_build_object('competitionId',p_id,'contractSha256',p_contract_sha,'policySha256',doc->>'policySha256','footballImageText',image,'footballSha256',encode(sha256(convert_to(image,'UTF8')),'hex'));
end$$;
create function public.get_mfa_nl_reviewed_source_contract(p_competition_id bigint,p_contract_sha text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare doc jsonb;begin doc:=private_mfa_nl_history.contract(p_competition_id,p_contract_sha);return jsonb_build_object('competitionId',p_competition_id,'contractSha256',p_contract_sha,'policySha256',doc->>'policySha256','contractDocument',doc);end$$;
create function public.get_mfa_nl_reviewed_source_state(p_competition_id bigint,p_main_sha text,p_contract_sha text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare result jsonb;begin result:=private_mfa_nl_history.source_state_core(p_competition_id,p_main_sha,p_contract_sha,clock_timestamp());perform private_mfa_nl_history.opening(p_competition_id,clock_timestamp());return result;end$$;

create function public.record_mfa_nl_reviewed_import(p_competition_id bigint,p_main_sha text,p_contract_sha text,p_football_sha text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare state jsonb;prior private_mfa_nl_history.import_receipt%rowtype;begin
 state:=private_mfa_nl_history.source_state_core(p_competition_id,p_main_sha,p_contract_sha,clock_timestamp());
 perform private_mfa_nl_history.release_require(p_football_sha~'^[a-f0-9]{64}$'and p_football_sha=state->>'footballSha256','externally verified exact native football SHA differs');
 select *into prior from private_mfa_nl_history.import_receipt where competition_id=p_competition_id and main_sha=p_main_sha;
 if prior.competition_id is not null then perform private_mfa_nl_history.release_require(prior.contract_sha=p_contract_sha and prior.football_sha=p_football_sha and prior.football_image_text=state->>'footballImageText'and prior.bootstrap_before_sha=state->>'bootstrapBeforeSha256','same-commit import receipt immutable');
 else insert into private_mfa_nl_history.import_receipt(competition_id,main_sha,contract_sha,bootstrap_before_sha,football_sha,football_image_text)values(p_competition_id,p_main_sha,p_contract_sha,state->>'bootstrapBeforeSha256',p_football_sha,state->>'footballImageText');end if;
 perform private_mfa_nl_history.opening(p_competition_id,clock_timestamp());return jsonb_build_object('competitionId',p_competition_id,'mainCommit',p_main_sha,'contractSha256',p_contract_sha,'footballSha256',p_football_sha,'bootstrapBeforeSha256',state->>'bootstrapBeforeSha256');
end$$;
create function private_mfa_nl_history.priced_state_sha(p_id bigint)returns text language sql stable security definer set search_path=public,pg_temp as $$select encode(sha256(convert_to(jsonb_build_object('nativeStateSha256',private_historical_statistics.state_sha256(p_id),'football',private_mfa_nl_history.football_image(p_id),'derived',private_mfa_nl_history.protected_current(p_id)-array['rounds','matches','players','teams','appearances','goals'])::text,'UTF8')),'hex')$$;
create function public.record_mfa_nl_reviewed_prices(p_competition_id bigint,p_main_sha text,p_contract_sha text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare state jsonb;imported private_mfa_nl_history.import_receipt%rowtype;sha text;begin
 state:=private_mfa_nl_history.source_state_core(p_competition_id,p_main_sha,p_contract_sha,clock_timestamp());
 select *into imported from private_mfa_nl_history.import_receipt where competition_id=p_competition_id and main_sha=p_main_sha;
 perform private_mfa_nl_history.release_require(imported.competition_id=p_competition_id and imported.contract_sha=p_contract_sha and imported.football_sha=state->>'footballSha256'and imported.football_image_text=state->>'footballImageText'and imported.bootstrap_before_sha=state->>'bootstrapBeforeSha256','fresh same-commit verified import required; football changed');
 sha:=private_mfa_nl_history.priced_state_sha(p_competition_id);
 insert into private_mfa_nl_history.price_receipt values(p_competition_id,p_main_sha,p_contract_sha,imported.football_sha,sha,clock_timestamp())on conflict(competition_id,main_sha)do update set contract_sha=excluded.contract_sha,football_sha=excluded.football_sha,state_sha=excluded.state_sha,recorded_at=excluded.recorded_at;
 perform private_mfa_nl_history.opening(p_competition_id,clock_timestamp());return jsonb_build_object('competitionId',p_competition_id,'mainCommit',p_main_sha,'contractSha256',p_contract_sha,'footballSha256',imported.football_sha,'pricedStateSha256',sha);
end$$;

create function private_mfa_nl_history.release_core(p_id bigint,p_main_sha text,p_contract_sha text,p_expected_preview_sha text,p_activate boolean,p_clock timestamptz)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare state jsonb;doc jsonb;imported private_mfa_nl_history.import_receipt%rowtype;priced private_mfa_nl_history.price_receipt%rowtype;prices jsonb;cost numeric;preview jsonb;sha text;begin
 state:=private_mfa_nl_history.source_state_core(p_id,p_main_sha,p_contract_sha,p_clock);doc:=private_mfa_nl_history.contract(p_id,p_contract_sha);
 select *into imported from private_mfa_nl_history.import_receipt where competition_id=p_id and main_sha=p_main_sha;
 select *into priced from private_mfa_nl_history.price_receipt where competition_id=p_id and main_sha=p_main_sha;
 perform private_mfa_nl_history.release_require(imported.competition_id=p_id and priced.competition_id=p_id and imported.contract_sha=p_contract_sha and priced.contract_sha=p_contract_sha and imported.football_sha=state->>'footballSha256'and imported.football_image_text=state->>'footballImageText'and priced.football_sha=imported.football_sha and priced.recorded_at>=imported.recorded_at and priced.state_sha=private_mfa_nl_history.priced_state_sha(p_id),'fresh same-commit import/prices and unchanged native football/state required');
 perform private_mfa_nl_history.release_require(not exists(select 1 from public.zliti_igralci((select slug from private_mfa_nl_history.target(p_id)),'mfa')where preskok is null),'unresolved player identity collision');
 prices:=public.stanje_lige(p_id);cost:=public.najcenejsi_kader(prices->'igralci');
 perform private_mfa_nl_history.release_require((prices->>'klubov')::int=(doc->>'expectedCurrentClubCount')::int and(prices->>'nastopov_s_klopi')::int>0 and cost is not null and cost<=100 and(prices->>'najvisja_cena')::numeric>=8 and coalesce((prices->>'privzetih')::numeric/nullif((prices->>'aktivnih')::numeric,0),1)<=0.7 and(prices->>'golov_brez_nastopa')::int=0,'current club/bench/varied actual prices and affordable legal15 required');
 perform private_mfa_nl_history.release_require(not exists(select distinct p.team_id from players p where p.competition_id=p_id and p.active except select distinct(tid)from jsonb_array_elements(state->'fixtureBindings')x cross join lateral(values((x->>'homeTeamId')::bigint),((x->>'awayTeamId')::bigint))v(tid))and not exists(select distinct p.team_id from players p where p.competition_id=p_id and p.active except select distinct p.team_id from players p join appearances a on a.player_id=p.id and a.team_id=p.team_id join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where p.competition_id=p_id and r.competition_id=p_id and r.season='2026/27'and p.active and p.position='GK'and p.position_source in('zapisnik','admin','klub')and a.is_goalkeeper and a.started and m.statistics_status='available'and m.imported_at is not null),'current trusted goalkeeper required for every selectable source club');
 preview:=jsonb_build_object('schemaVersion',1,'competitionId',p_id,'mainCommit',p_main_sha,'contractSha256',p_contract_sha,'sourceArtifact',doc->'sourceArtifact','policySha256',doc->>'policySha256','bootstrapBeforeSha256',state->>'bootstrapBeforeSha256','bootstrapMainCommit',(select main_sha from private_mfa_nl_history.bootstrap_receipt where competition_id=p_id),'footballSha256',imported.football_sha,'importRecordedAt',imported.recorded_at,'priceReceipt',to_jsonb(priced),'opening',state->'opening','markers',state->'markers','headerBindings',state->'headerBindings','fixtureBindings',state->'fixtureBindings','priceSummary',prices-'igralci','cheapestLegal15',cost);
 sha:=encode(sha256(convert_to(preview::text,'UTF8')),'hex');
 if p_activate then
  perform private_mfa_nl_history.release_require(p_expected_preview_sha=sha and not exists(select 1 from private_mfa_nl_history.release_receipt where competition_id=p_id),'reviewed preview digest changed or release already used');
  perform private_historical_statistics.authorize_release(p_id,doc->>'policyId',doc->>'policySha256',sha);
  update competitions set active=true where id=p_id and not active;perform private_mfa_nl_history.release_require(found,'inactive activation row changed');
  insert into private_mfa_nl_history.release_receipt(competition_id,main_sha,contract_sha,preview_sha,result)values(p_id,p_main_sha,p_contract_sha,sha,preview);
 end if;
 return jsonb_build_object('preview',preview,'previewSha256',sha,'active',p_activate);
end$$;
create function public.check_mfa_nl_reviewed_release(p_competition_id bigint,p_main_sha text,p_contract_sha text,p_expected_preview_sha text default null,p_activate boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare result jsonb;begin result:=private_mfa_nl_history.release_core(p_competition_id,p_main_sha,p_contract_sha,p_expected_preview_sha,p_activate,clock_timestamp());perform private_mfa_nl_history.opening(p_competition_id,clock_timestamp());return result;end$$;
create function public.get_mfa_nl_reviewed_release_receipt(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_mfa_nl_history.release_require(exists(select 1 from private_mfa_nl_history.target(p_competition_id))and exists(select 1 from private_mfa_nl_history.source_contract where competition_id=p_competition_id),'stored source contract and fixed receipt target required');
 return jsonb_build_object('bootstrap',(select to_jsonb(b)-'before_image_text'from private_mfa_nl_history.bootstrap_receipt b where competition_id=p_competition_id),'contractSha256',(select contract_sha256 from private_mfa_nl_history.source_contract where competition_id=p_competition_id),'imports',(select coalesce(jsonb_agg(to_jsonb(i)-'football_image_text'order by recorded_at,main_sha),'[]')from private_mfa_nl_history.import_receipt i where competition_id=p_competition_id),'prices',(select coalesce(jsonb_agg(to_jsonb(p)order by recorded_at,main_sha),'[]')from private_mfa_nl_history.price_receipt p where competition_id=p_competition_id),'release',(select to_jsonb(r)from private_mfa_nl_history.release_receipt r where competition_id=p_competition_id),'active',(select active from competitions where id=p_competition_id));
end$$;
revoke all on all functions in schema private_mfa_nl_history from public,anon,authenticated,service_role;
revoke all on function public.get_mfa_nl_reviewed_source_contract(bigint,text),public.get_mfa_nl_reviewed_source_state(bigint,text,text),public.record_mfa_nl_reviewed_import(bigint,text,text,text),public.record_mfa_nl_reviewed_prices(bigint,text,text),public.check_mfa_nl_reviewed_release(bigint,text,text,text,boolean),public.get_mfa_nl_reviewed_release_receipt(bigint)from public,anon,authenticated;
grant execute on function public.get_mfa_nl_reviewed_source_contract(bigint,text),public.get_mfa_nl_reviewed_source_state(bigint,text,text),public.record_mfa_nl_reviewed_import(bigint,text,text,text),public.record_mfa_nl_reviewed_prices(bigint,text,text),public.check_mfa_nl_reviewed_release(bigint,text,text,text,boolean),public.get_mfa_nl_reviewed_release_receipt(bigint)to service_role;
